      {todo.title}
      {todo.status === 'done' ? ' (done)' : null}{' '}
      <button type="button" onClick={complete}>
        Complete
      </button>
      {error ? <ErrorMessage>{error}</ErrorMessage> : null}
    </li>
  )
}
